#include <stdio.h>

int main() {
    // Using eight printf statements
    printf("********\n");
    printf("********\n");
    printf("********\n");
    printf("********\n");
    printf("********\n");
    printf("********\n");

    printf("\n"); // Separator for clarity

    // Using as few printf statements as possible (e.g., using a loop)
    // For a 6x8 pattern, a loop is efficient
    for (int i = 0; i < 6; i++) {
        printf("********\n");
    }
    // Alternatively, for a truly minimal number of printf calls 
    // without loops, concatenate the string (though less readable):
    // printf("********\n********\n********\n********\n********\n********\n");

    return 0;
}
```
